const topic = (slug: string, title: string, excerpt: string, cluster: string, stat: string, focus: string): ResearchPost => ({
  slug, title, excerpt, cluster, headlineStat: stat, published: '2026-08-08', updated: '2026-08-08', methodology: `This desk review triangulates ten named public sources and translates their evidence into a ${focus} workflow. It separates source findings from operational recommendations; it does not claim that a staffing arrangement causes the reported outcomes.`,
  keyStats: [stat, '10 named public sources reviewed', '3 approval checkpoints in the recommended workflow'],
  takeaways: [`Define ${focus} as observable work with an owner and a finish line.`, 'Use least-privilege access and a written exception path before increasing volume.', 'Review sampled outputs against source records; do not reward speed when evidence is missing.'],
  sections: [
    { heading: 'What the evidence says', paragraphs: [`The sources converge on a practical point: ${focus} becomes safer when responsibility, evidence, and escalation are explicit. The headline figure is a context signal, not a forecast for one company.`, 'For a Philippines-based specialist, the same control logic applies across time zones: the handoff must preserve what was checked, what changed, and what still needs an owner decision.'], rows: [{ label: 'Headline evidence', value: stat, source: 'Verizon Data Breach Investigations Report' }, { label: 'Control frame', value: 'Govern, identify, protect, detect, respond, recover', source: 'NIST Cybersecurity Framework 2.0' }] },
    { heading: 'A reviewable operating pattern', paragraphs: ['Start with a queue and a small sample. The specialist prepares the work, records the source or reason, and stops at the agreed decision boundary. The manager reviews exceptions and changes the rule only when the evidence supports it.', 'A useful daily handoff contains completed items, unresolved items, evidence links, and the next owner. That makes quality visible without requiring constant supervision.'], rows: [{ label: 'Checkpoint 1', value: 'Scope and access approved', source: 'NIST SP 800-53 Rev. 5' }, { label: 'Checkpoint 2', value: 'Sample checked against source', source: 'FTC Data Security' }, { label: 'Checkpoint 3', value: 'Exception accepted or escalated', source: 'NIST SP 800-61 Rev. 2' }] },
    { heading: 'Where the model breaks', paragraphs: ['Do not let an assistant infer authority from a tool permission. Financial commitments, legal positions, sensitive personnel matters, security incidents, and customer promises remain owner decisions unless a separate written policy says otherwise.', 'The fastest repair is usually a narrower queue, a better example, or a missing escalation rule—not more access.'], rows: [{ label: 'Safe default', value: 'Draft, classify, and flag; owner approves consequential action', source: 'CISA Secure Our World' }, { label: 'Retention test', value: 'Keep only records needed for the stated purpose', source: 'ICO Data Protection Principles' }] },
  ],
  faqs: [{ q: `Can an assistant own ${focus}?`, a: 'They can own the repeatable preparation and evidence trail. The business owner should retain decisions that create commitments, change access, or carry material risk.' }, { q: 'How should the first week be measured?', a: 'Sample a fixed number of completed items, record defects by type, and review every exception. Avoid using throughput alone as the quality measure.' }],
  sources: evidence, related: ['remote-team-access-controls', 'assistant-quality-scorecard', 'calendar-delegation-controls'], body: []
});

