const aug13Topic = (slug: string, title: string, excerpt: string, cluster: string, stat: string, focus: string, related: readonly string[]): ResearchPost => {
  const base = currentBatchTopic(slug, title, excerpt, cluster, stat, focus, related, { published: '2026-08-13', updated: '2026-08-13' });
  const extra: ResearchSection[] = [
    { heading: 'How to define the unit of analysis', paragraphs: [
      `A useful ${focus} review begins by naming the unit being measured. That might be one request, one queue item, one handoff, one approval, or one record change. Mixing units makes a small task look equivalent to a consequential case and hides the work that consumes the most judgement. Record the period covered, the population included, and the exclusions before interpreting a result.`,
      `For outsourced work, the unit should also identify the role boundary. A Philippines-based specialist may prepare evidence, classify an item, or draft a response, while an owner decides whether the business will make a commitment. Treating preparation and approval as one unit makes it impossible to tell whether a delay came from incomplete work, an unavailable decision-maker, or an intentionally held control.`,
    ], rows: [{ label: 'Required unit', value: `One observable ${focus} case with a start point and disposition`, source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Required period', value: 'A stated review window with excluded cases recorded', source: 'ILO Working from Home Report' }] },
    { heading: 'What a defensible sample looks like', paragraphs: [
      `A sample should represent the work that actually arrives, not only the easiest items. Separate routine cases from urgent, incomplete, sensitive, and reopened cases. If the review includes only clean examples, it measures the quality of selection rather than the quality of ${focus}. Keep the denominator visible and explain why any case was excluded.`,
      `A small team does not need a complicated statistical program to learn from a queue. It does need consistent labels. For each sampled case, record the input quality, evidence checked, action prepared, decision boundary reached, elapsed time, and defect category. That record supports bounded interpretation: it can show where the process is failing, but it cannot prove that one staffing arrangement caused the result.`,
    ], rows: [{ label: 'Minimum sample fields', value: 'Input, evidence, action, owner, elapsed time, exception, outcome', source: 'CIS Controls v8' }, { label: 'Interpretation limit', value: 'Descriptive evidence supports process decisions; it is not causal proof', source: 'This review methodology' }] },
    { heading: 'Inputs, context, and confounders', paragraphs: [
      `The same ${focus} result can mean different things when the input conditions differ. A queue may age because demand rose, because requests became more complex, because the owner changed the approval rule, or because the available review window narrowed. Record those contextual changes rather than assigning every variance to individual performance.`,
      `Time-zone work adds a measurable handoff condition. Note when an item became ready, when it entered the review window, and when the next owner could act. This separates production time from waiting time. It also avoids a common mistake: comparing a daytime queue with an overnight queue as if both had identical access to decisions, clarifications, and source systems.`,
    ], rows: [{ label: 'Context variables', value: 'Demand, complexity, review availability, handoff timing, and policy changes', source: 'ILO Working from Home Report' }, { label: 'Security context', value: 'Data access and purpose must remain limited to the work being assessed', source: 'ICO Data Protection Principles' }] },
    { heading: 'Decision rules and escalation boundaries', paragraphs: [
      `A review becomes operationally useful when it states what happens next at each threshold. If evidence is complete and the action is reversible, the specialist may prepare the next step. If the request changes money, access, legal position, customer obligation, or sensitive data exposure, stop and route it to the named owner. Thresholds should be written in observable terms, not in vague instructions such as “use good judgement.”`,
      `Escalation should carry the evidence needed to decide. Include the original request, the relevant record, what was checked, what remains uncertain, and the decision required. This reduces repeated questions and lets the owner distinguish a true urgent case from a request that is merely inconvenient. The route should also state what the specialist may do while waiting, such as preserve a draft or mark the case pending.`,
    ], rows: [{ label: 'Routine disposition', value: 'Prepare, document, and queue for the approved review step', source: 'NIST SP 800-53 Revision 5' }, { label: 'Hard stop', value: 'Escalate changes with financial, legal, privacy, access, or customer impact', source: 'CISA Secure Our World' }] },
    { heading: 'Limitations and what the evidence cannot show', paragraphs: [
      `This review is bounded by the quality and scope of public guidance. The named sources provide control principles, working-condition context, or security practices; they do not provide a universal benchmark for every small business or every Philippines-based team. Local law, contract terms, sector requirements, and the sensitivity of the records can change the appropriate control.`,
      `A process measure also has blind spots. A low defect rate may reflect strong work, easy inputs, or under-reporting. A longer elapsed time may reflect careful review rather than poor execution. Treat the measure as one piece of evidence and compare it with source completeness, exception quality, rework, and owner decisions. When the evidence conflicts, narrow the claim and gather another period of observations.`,
    ], rows: [{ label: 'Primary limitation', value: 'Public guidance is transferable context, not a company-specific causal estimate', source: 'This review methodology' }, { label: 'Quality safeguard', value: 'Pair throughput with accuracy, evidence completeness, rework, and escalation quality', source: 'FTC Data Security' }] },
    { heading: 'Conclusion for owners and operators', paragraphs: [
      `The practical conclusion is narrower than “delegate more.” A sound ${focus} model makes the work observable, measures the right unit, preserves the evidence, and keeps consequential decisions with an accountable owner. That design gives a small business a way to expand repeatable support while learning where ambiguity or risk is accumulating.`,
      `Start with one defined queue and one review period. Publish the scope, access boundary, sample fields, escalation route, and interpretation limits before judging the result. After the period ends, change one rule at a time and preserve the old evidence. This makes improvement traceable and keeps a new exception from silently becoming permanent authority.`,
    ], rows: [{ label: 'Recommended first step', value: `Run one bounded review period for ${focus} and preserve the evidence trail`, source: 'NIST Cybersecurity Framework 2.0' }, { label: 'Success condition', value: 'Owners can explain what was measured, what changed, and what remains uncertain', source: 'NIST SP 800-61 Revision 2' }] },
  ];
  return { ...base, sections: [...base.sections, ...extra] };
};

